// A bounded image trail; no continuous loop and no dependence on hover for content.
const intro=document.querySelector('.intro'),trail=intro.querySelector('.cursor-trail'),finePointer=matchMedia('(hover: hover) and (pointer: fine)');
const trailAssets=['jardim','quarto','cafe','cozinha','boutique','varanda'];let lastX=0,lastY=0,lastTime=0,trailIndex=0;
intro.addEventListener('pointermove',event=>{if(motion.matches||!finePointer.matches||event.target.closest('a,button'))return;const now=performance.now();if(now-lastTime<150||Math.hypot(event.clientX-lastX,event.clientY-lastY)<75)return;lastTime=now;lastX=event.clientX;lastY=event.clientY;const rect=intro.getBoundingClientRect(),img=document.createElement('img');img.className='trail-photo';img.alt='';img.src=`assets/${trailAssets[trailIndex++%trailAssets.length]}.jpg`;const x=Math.max(0,Math.min(rect.width-165,event.clientX-rect.left-82)),y=Math.max(0,Math.min(rect.height-210,event.clientY-rect.top-105));img.style.left=x+'px';img.style.top=y+'px';trail.append(img);while(trail.children.length>6)trail.firstElementChild.remove();const rot=(trailIndex%2?1:-1)*9;const animation=img.animate([{opacity:0,transform:`translateY(20px) rotate(${rot}deg) scale(.8)`},{opacity:1,transform:`translateY(0) rotate(${rot}deg) scale(1)`,offset:.2},{opacity:1,transform:`translateY(-8px) rotate(${rot}deg) scale(1)`,offset:.55},{opacity:0,transform:`translateY(-40px) rotate(${rot*.5}deg) scale(.96)`}],{duration:1300,easing:'cubic-bezier(.2,.65,.3,1)'});animation.onfinish=()=>img.remove()});
